import {precision} from './precision.js';
export const safeImageReference=value=>/^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/=\s]+$/.test(value);
export function unsafeSvgAttribute(name,value){if(/^on/i.test(name)||name==='src'||/href$/i.test(name))return /^on/i.test(name)||!value.trim().startsWith('#')&&!safeImageReference(value.trim());return /(?:url\s*\(|@import|expression\s*\(|javascript\s*:|behavior\s*:|\\)/i.test(value)&&!/^url\(\s*["']?#[\w:.-]+["']?\s*\)$/i.test(value.trim());}
const dangerous=new Set(['script','foreignobject','iframe','object','embed','animate','animatetransform','animatemotion','set','discard']);
export function sanitizeSvgDocument(xml){if(xml.querySelector('parsererror')||xml.documentElement.localName?.toLowerCase()!=='svg'&&xml.documentElement.tagName!=='svg')throw Error('SVG inválido');const stack=[[xml.documentElement,0]];let count=0;while(stack.length){const [el,depth]=stack.pop();if(++count>precision.maxObjects*4||depth>precision.maxDepth)throw Error('El SVG supera el límite de complejidad.');if(dangerous.has((el.localName||el.tagName).toLowerCase())){el.remove();continue;}if((el.localName||el.tagName).toLowerCase()==='style'&&/(?:@import|url\s*\(|\\|expression\s*\(|behavior\s*:)/i.test(el.textContent)){el.remove();continue;}for(const a of [...el.attributes])if(unsafeSvgAttribute(a.name,a.value))el.removeAttribute(a.name);for(const child of el.children||[])stack.push([child,depth+1]);}return xml;}
export function sanitizeSvg(text){if(typeof text!=='string'||text.length>20*1024*1024||/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('SVG inválido o demasiado complejo');return new XMLSerializer().serializeToString(sanitizeSvgDocument(new DOMParser().parseFromString(text,'image/svg+xml')));}
// Native JSON must not bypass the sanitization applied by the SVG picker.
export function assertSafeImageSource(src){if(typeof src!=='string'||src.length>28*1024*1024)throw Error('Imagen no admitida.');if(safeImageReference(src))return;if(!/^data:image\/svg\+xml;base64,[A-Za-z0-9+/=\s]+$/.test(src))throw Error('Imagen no admitida.');let text;try{text=atob(src.slice(src.indexOf(',')+1));}catch{throw Error('SVG codificado inválido.');}if(/<!DOCTYPE|<!ENTITY|<(?:\w+:)?(?:script|foreignObject|iframe|object|embed|animate\w*|set)\b|\bon\w+\s*=|@import|\\|expression\s*\(/i.test(text))throw Error('El proyecto contiene un SVG no seguro.');for(const match of text.matchAll(/(?:\b(?:[\w-]+:)?href|\bsrc)\s*=\s*(["'])(.*?)\1/gi))if(!match[2].startsWith('#')&&!safeImageReference(match[2]))throw Error('El SVG contiene recursos externos no admitidos.');for(const match of text.matchAll(/url\s*\((.*?)\)/gi))if(!/^\s*["']?#[\w:.-]+["']?\s*$/.test(match[1]))throw Error('El SVG contiene recursos externos no admitidos.');}
